import java.util.*;

public class Main {
    static final long M1 = 1000000007L, M2 = 998244353L, B1 = 911382323L, B2 = 972663749L;

    static class Hasher {
        long[] h1, h2, p1, p2;

        Hasher(String s) {
            int n = s.length();
            h1 = new long[n + 1];
            h2 = new long[n + 1];
            p1 = new long[n + 1];
            p2 = new long[n + 1];
            p1[0] = 1;
            p2[0] = 1;
            for (int i = 0; i < n; i++) {
                long v = s.charAt(i) - 'a' + 1;
                h1[i + 1] = (h1[i] * B1 + v) % M1;
                h2[i + 1] = (h2[i] * B2 + v) % M2;
                p1[i + 1] = p1[i] * B1 % M1;
                p2[i + 1] = p2[i] * B2 % M2;
            }
        }

        long key(int l, int r) {
            long a = ((h1[r] - h1[l] * p1[r - l]) % M1 + M1) % M1;
            long b = ((h2[r] - h2[l] * p2[r - l]) % M2 + M2) % M2;
            return a * M2 + b;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();

        int n = s.length();
        String rs = new StringBuilder(s).reverse().toString();
        Hasher ha = new Hasher(s), hb = new Hasher(rs);
        int p = 1;
        for (int i = n; i >= 1; i--) {
            if (ha.key(0, i) == hb.key(n - i, n)) {
                p = i;
                break;
            }
        }
        System.out.println(new StringBuilder(s.substring(p)).reverse() + s);
    }
}
